198	16	\N	1	1	Report layout	\N	web.report_layout	qweb	web/views/report_templates.xml	primary	{"en_US": "<t name=\\"Report layout\\" t-name=\\"web.report_layout\\">&lt;!DOCTYPE html&gt;\\n        <html t-att-lang=\\"lang and lang.replace('_', '-')\\" t-att-data-report-margin-top=\\"data_report_margin_top\\" t-att-data-report-header-spacing=\\"data_report_header_spacing\\" t-att-data-report-dpi=\\"data_report_dpi\\" t-att-data-report-landscape=\\"data_report_landscape\\" t-att-web-base-url=\\"web_base_url\\">\\n            <head>\\n                <meta charset=\\"utf-8\\"/>\\n                <meta name=\\"viewport\\" content=\\"initial-scale=1\\"/>\\n                <title><t t-esc=\\"title or 'Odoo Report'\\"/></title>\\n                <t t-call-assets=\\"web.report_assets_common\\" t-autoprefix=\\"true\\"/>\\n                <!-- Temporary code: only used to maintain CSS for legacy HTML reports (full width...) -->\\n                <!-- Should be removed once the reports are fully converted. -->\\n                <script type=\\"text/javascript\\">\\n                    document.addEventListener('DOMContentLoaded', () =&gt; {\\n                        if (window.self !== window.top) {\\n                            document.body.classList.add(\\"o_in_iframe\\", \\"container-fluid\\");\\n                            document.body.classList.remove(\\"container\\");\\n                        }\\n                    });\\n                </script>\\n            </head>\\n            <body t-attf-class=\\"o_body_html {{'container' if not full_width else 'container-fluid'}} overflow-x-hidden\\" t-att-dir=\\"env['res.lang']._get_data(code=lang or env.user.lang).direction or 'ltr'\\">\\n                <div id=\\"wrapwrap\\">\\n                    <main>\\n                        <t t-out=\\"0\\"/>\\n                    </main>\\n                </div>\\n            </body>\\n        </html>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Report layout" t-name="web.report_layout">&lt;!DOCTYPE html&gt;\n        <html t-att-lang="lang and lang.replace('_', '-')" t-att-data-report-margin-top="data_report_margin_top" t-att-data-report-header-spacing="data_report_header_spacing" t-att-data-report-dpi="data_report_dpi" t-att-data-report-landscape="data_report_landscape" t-att-web-base-url="web_base_url">\n            <head>\n                <meta charset="utf-8"/>\n                <meta name="viewport" content="initial-scale=1"/>\n                <title><t t-esc="title or 'Odoo Report'"/></title>\n                <t t-call-assets="web.report_assets_common" t-autoprefix="true"/>\n                <!-- Temporary code: only used to maintain CSS for legacy HTML reports (full width...) -->\n                <!-- Should be removed once the reports are fully converted. -->\n                <script type="text/javascript">\n                    document.addEventListener('DOMContentLoaded', () =&gt; {\n                        if (window.self !== window.top) {\n                            document.body.classList.add("o_in_iframe", "container-fluid");\n                            document.body.classList.remove("container");\n                        }\n                    });\n                </script>\n            </head>\n            <body t-attf-class="o_body_html {{'container' if not full_width else 'container-fluid'}} overflow-x-hidden" t-att-dir="env['res.lang']._get_data(code=lang or env.user.lang).direction or 'ltr'">\n                <div id="wrapwrap">\n                    <main>\n                        <t t-out="0"/>\n                    </main>\n                </div>\n            </body>\n        </html>\n    </t>\n\n    	f	t	2025-12-05 09:32:14.817167	2025-12-05 09:32:14.817167
